                    "sql": "CREATE OR REPLACE TABLE MEDMONGERS_DB.MAPLEMONK.MEDMONGERS_FLIPKART_ORDER_FULFILMENT_FACT_ITEMS AS SELECT TRY_CAST(order_date AS DATE) AS order_date, TRY_CAST(NULLIF(REPLACE(order_approval_date,\'\"\',\'\'),\'\') AS DATE) AS order_approval_date, REPLACE(REPLACE(REPLACE(sku, \'\"\', \'\'), \'SKU:\', \'\'), \'sku:\', \'\') AS sku, order_id AS reference_code, order_id, TRY_CAST(NULLIF(order_cancellation_date,\'\') AS DATE) AS cancellation_date, REPLACE(cancellation_reason,\'_\',\' \') AS cancellation_reason, TRY_CAST(NULLIF(order_ready_for_dispatch_on_date,\'\') AS TIMESTAMP) AS order_ready_for_dispatch_on_date, TRY_CAST(NULLIF(dispatch_after_date,\'\') AS TIMESTAMP) AS manifest_date, TRY_CAST(NULLIF(dispatch_by_date,\'\') AS TIMESTAMP) AS dispatch_date, CASE WHEN deliver_by_date=\'N\' THEN NULL ELSE TRY_CAST(deliver_by_date AS DATE) END AS delivery_date, CASE WHEN UPPER(pickup_logistics_partner) LIKE \'%COD%\' THEN \'cod\' ELSE \'prepaid\' END AS payment_mode, pickup_logistics_partner AS courier, TRY_CAST(NULLIF(order_return_approval_date,\'\') AS DATE) AS return_approval_date, TRY_CAST(NULLIF(order_service_completion_date,\'\') AS TIMESTAMP) AS order_service_completion_date, return_id, REPLACE(return_reason,\'_\',\' \') AS return_reason, REPLACE(return_sub_reason,\'_\',\' \') AS return_sub_reason, REPLACE(order_item_id,\'OI:\',\'\') AS order_item_id, REPLACE(product_title,\'\"\',\'\') AS product_name, fulfilment_type, fulfilment_source, REPLACE(order_item_status,\'_\',\' \') AS order_item_status, REPLACE(delivery_tracking_id,\'DTr:\',\'\') AS fk_awb FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY order_id,order_item_id ORDER BY order_return_approval_date DESC ) rn FROM MAPLEMONK.FLIPKART_MEDMONGERS_ORDERS ) WHERE rn=1; create or replace table medmongers_db.maplemonk.medmongers_Flipkart_sales_fact_items as select \'Flipkart\' shop_name, f.order_item_status, s.\"Order ID\" order_id, s.\"Order ID\" order_name, \"Fulfilment Type\" fulfilment_type, f.dispatch_date, f.delivery_date, f.payment_mode, NULL as customer_id, NULL as phone, \"HSN Code\" hsn_code, s.\"Event Sub Type\" event_type, s.\"Order Type\" as payment_type, cast(NULL as string) as tags, s.\"Order Item ID\" as line_item_id, cast(replace(replace(s.sku,\'\"\',\'\'),\'SKU:\',\'\') as string) as SKU, replace(s.FSN,\'\"\',\'\') as product_id, case when s.\"Event Sub Type\" = \'Return\' then 1 else 0 end as is_refund, cast(NULL as string) as city, case when s.\"Customer\'s Delivery State\" = \'-\' then (case when s.\"Customer\'s Billing State\" = \'-\' then null else s.\"Customer\'s Billing State\"end) else s.\"Customer\'s Delivery State\" end as state, case when s.\"Customer\'s Billing State\" = \'-\' then (case when s.\"Customer\'s Billing Pincode\" = \'-\' then null else s.\"Customer\'s Billing Pincode\" end) else s.\"Customer\'s Delivery State\" end as pincode, replace(\"Product Title/Description\",\'\"\',\'\') as PRODUCT_NAME, cast(Null as string) as category, try_Cast(left(\"Order Date\",10) as date) order_Date, try_Cast(left(\"Buyer Invoice Date\",10) as date) invoice_Date, cast(\"TDS Rate\" as float) tds_rate, cast(\"VAT Rate\" as float) VAT_Rate, cast(\"CGST Rate\" as float) CGST_Rate, cast(\"IGST Rate\" as float) IGST_Rate, cast(\"CST Amount\" as float) CST_Amount, cast(\"TDS Amount\" as float) TDS_Amount, cast(\"VAT Amount\" as float) VAT_Amount, cast(\"CGST Amount\" as float) CGST_Amount, cast(\"IGST Amount\" as float) IGST_Amount, cast(\"Type of tax\" as float) Type_of_tax, case when \"Usual Price\" = \'NA\' then null else cast(\"Usual Price\" as float) end Usual_Price, \"Seller GSTIN\" Seller_GSTIN, abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)) as line_item_sales, abs(ifnull(cast(\"Shipping Charges\" as float),0) )as shipping_price, abs(ifnull(cast(\"Item Quantity\" as float),0)) as quantity, abs(ifnull(cast(\"Total TCS Deducted\" as float),0)) as tax, abs(div0(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0),(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)+ifnull(cast(\"Total TCS Deducted\" as float),0)))) as overall_tax_rate, abs(ifnull(cast(\"Total Discount\" as float),0)) as discount, div0(abs(ifnull(cast(\"Total Discount\" as float),0)),(1-div0(abs(ifnull(cast(\"Total TCS Deducted\" as float),0)),(abs(ifnull(cast(\"Total TCS Deducted\" as float),0))+abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)))))) as discount_before_tax, (abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)) - div0(abs(ifnull(cast(\"Total Discount\" as float),0)),(1-div0(abs(ifnull(cast(\"Total TCS Deducted\" as float),0)),(abs(ifnull(cast(\"Total TCS Deducted\" as float),0))+abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0))))))) as gross_sales_before_tax, abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)) as total_sales, \"Beneficiary Name\" as name, cast(null as string) as email, \"Order Shipped From (State)\" as Order_Shipped_From_State, \"Warehouse ID\" Warehouse_ID, \"Business Name\" Business_Name, cast(sm.product_name as string) mapped_product_name, cast(sm.product_category as string) mapped_product_category, cast(null as string) mapped_product_sub_Category, sm.commonsku, sm.mrp, sm.cost as cogs, sm.brand from ( select * from medmongers_db.maplemonk.flipkart_medmongers_sales where \"Order ID\" <> \'\' qualify row_number() over (partition by \"Order Item ID\",\"Order ID\", \"Buyer Invoice ID\" order by 1) = 1 ) s left join medmongers_db.MAPLEMONK.MEDMONGERS_FLIPKART_ORDER_FULFILMENT_FACT_ITEMS f on s.\"Order ID\" = f.order_id and s.\"Order Item ID\" = f.order_item_id left join ( select channel_sku, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, cost, mrp, brand from medmongers_db.maplemonk.medmongers_final_sku_master where final_marketplace = \'FLIPKART\' qualify row_number() over (partition by channel_sku order by channelname) = 1 ) sm on lower(trim(sm.channel_sku)) = lower(trim(cast(replace(replace(s.sku,\'\"\',\'\'),\'SKU:\',\'\') as string))) ;",
